<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue';
import { billingCall } from '../api/billing';
import { indiaStamp } from '../lib/cc';
const endpoint='life_slimming.api.cc_invoices.';
const emptyFilters=()=>{const today=indiaStamp().slice(0,10);return {query:'',mobile:'',branch:'',status:'',source:'',from_date:today,to_date:today};};
const filters=ref(emptyFilters()),applied=ref(emptyFilters()),options=ref({branches:[],sources:[],statuses:[]});
const rows=ref([]),total=ref(0),start=ref(0),more=ref(false);
const busy=ref(false),error=ref(''),optionsError=ref(''),invoice=ref(null),detailBusy=ref(false),detailError=ref(''),invoiceDialog=ref(null);
let listGeneration=0,detailGeneration=0,listController,detailController;
const money=(v,c='INR')=>new Intl.NumberFormat('en-IN',{style:'currency',currency:c||'INR',maximumFractionDigits:2}).format(Number(v||0));
const date=value=>value?new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(String(value).slice(0,10)+'T12:00:00')):'—';
const statusTone=value=>value==='Paid'?'paid':['Overdue','Unpaid'].includes(value)?'due':value==='Partly Paid'?'partial':'neutral';
const rangeText=computed(()=>!total.value?'No matching bills':`${start.value+1}–${Math.min(start.value+rows.value.length,total.value)} of ${total.value.toLocaleString('en-IN')} bills`);
const chips=computed(()=>Object.entries(applied.value).filter(([,value])=>value).map(([key,value])=>({key,label:({query:'Search',mobile:'Mobile',branch:'Branch',status:'Status',source:'Source',from_date:'From',to_date:'To'})[key],value:['from_date','to_date'].includes(key)?date(value):value})));
async function load(offset=0,useDraft=true){
  const selected={...(useDraft?filters.value:applied.value)};
  if(selected.from_date&&selected.to_date&&selected.from_date>selected.to_date){error.value='Choose an end date on or after the start date.';return;}
  if(selected.mobile&&selected.mobile.replace(/\D/g,'').length<4){error.value='Enter at least four digits for mobile search.';return;}
  const token=++listGeneration;listController?.abort();listController=new AbortController();busy.value=true;error.value='';
  try{
    const result=await billingCall(endpoint+'list_invoices',{...selected,start:offset},listController.signal);
    if(token!==listGeneration)return;
    rows.value=result.rows;total.value=result.total;more.value=result.more;start.value=offset;applied.value=selected;
  }catch(e){if(token===listGeneration&&e.name!=='AbortError'){error.value=e.message;rows.value=[];total.value=0;more.value=false;}}
  finally{if(token===listGeneration)busy.value=false;}
}
async function loadOptions(){optionsError.value='';try{options.value=await billingCall(endpoint+'filters');}catch{optionsError.value='Filter choices could not be loaded.';}}
function reset(){filters.value=emptyFilters();load();}
function quickRange(range){const today=indiaStamp().slice(0,10);filters.value.from_date=range==='today'?today:range==='month'?today.slice(0,7)+'-01':'';filters.value.to_date=range==='all'?'':today;load();}
async function open(name){
  const token=++detailGeneration;detailController?.abort();detailController=new AbortController();invoice.value=null;detailBusy.value=true;detailError.value='';
  await nextTick();if(token!==detailGeneration||!invoiceDialog.value)return;if(!invoiceDialog.value.open)invoiceDialog.value.showModal();
  try{const result=await billingCall(endpoint+'invoice',{name},detailController.signal);if(token===detailGeneration)invoice.value=result;}
  catch(e){if(token===detailGeneration&&e.name!=='AbortError')detailError.value=e.message;}
  finally{if(token===detailGeneration)detailBusy.value=false;}
}
function closed(){detailGeneration++;detailController?.abort();detailBusy.value=false;}
onMounted(()=>{load();loadOptions();});
onBeforeUnmount(()=>{listGeneration++;detailGeneration++;listController?.abort();detailController?.abort();});
</script>

<template>
<div class="bills-workspace">
  <header class="bills-heading"><div><span class="eyebrow">CALL CENTRE WORKSPACE</span><h1>Invoices <span>/ Bills</span></h1><p>Find a client’s bill, check its source and review outstanding balances.</p></div><span class="view-only"><span aria-hidden="true">◉</span> View only</span></header>
  <section class="filter-card" aria-label="Filter invoices">
    <div class="filter-heading"><h2>Find a bill</h2><div class="quick-ranges"><button type="button" @click="quickRange('today')">Today</button><button type="button" @click="quickRange('month')">This month</button><button type="button" @click="quickRange('all')">All dates</button></div></div>
    <form @submit.prevent="load()">
      <div class="search-row"><label class="wide-search"><span>Invoice or client</span><input v-model="filters.query" type="search" placeholder="Search bill number, client name, ID or mobile…"></label><label><span>Mobile number</span><input v-model="filters.mobile" type="tel" inputmode="tel" placeholder="Enter mobile or last 4 digits"></label></div>
      <div class="filter-grid"><label><span>From date</span><input v-model="filters.from_date" type="date" :max="filters.to_date||undefined"></label><label><span>To date</span><input v-model="filters.to_date" type="date" :min="filters.from_date||undefined"></label><label><span>Branch</span><select v-model="filters.branch"><option value="">All branches</option><option v-for="branch in options.branches" :key="branch">{{branch}}</option></select></label><label><span>Payment status</span><select v-model="filters.status"><option value="">All statuses</option><option v-for="status in options.statuses" :key="status">{{status}}</option></select></label><label><span>Client source</span><select v-model="filters.source"><option value="">All sources</option><option v-for="source in options.sources" :key="source">{{source}}</option></select></label></div>
      <div class="filter-actions"><span v-if="!chips.length" class="filter-help">Showing today’s bills by default. Use All dates to search the full history.</span><span v-else class="filter-help">{{chips.length}} active {{chips.length===1?'filter':'filters'}}</span><button type="button" class="reset-button" @click="reset">Reset filters</button><button class="apply-button" :disabled="busy">{{busy?'Searching…':'Apply filters'}} <span aria-hidden="true">→</span></button></div>
    </form>
    <p v-if="optionsError" class="options-error" role="status">{{optionsError}} <button @click="loadOptions">Retry</button></p>
    <div v-if="chips.length" class="filter-chips"><span v-for="chip in chips" :key="chip.key">{{chip.label}}: <b>{{chip.value}}</b></span></div>
  </section>
  <div v-if="error" class="bill-error" role="alert">{{error}} <button @click="load()">Try again</button></div>
  <section class="bill-results" :aria-busy="busy">
    <header><div><h2>Invoice register</h2><span>{{busy?'Updating results…':rangeText}}</span></div><button class="refresh-button" :disabled="busy" @click="load(start,false)"><span aria-hidden="true">↻</span> Refresh</button></header>
    <div class="table-scroll"><table><thead><tr><th>Invoice / Date</th><th>Client</th><th>Mobile number</th><th>Branch</th><th>Source</th><th>Status</th><th class="amount">Bill total</th><th class="amount">Outstanding</th><th><span class="sr-only">View bill</span></th></tr></thead><tbody>
      <tr v-for="row in rows" :key="row.name"><td><button class="invoice-link" @click="open(row.name)">{{row.name}}</button><small>{{date(row.posting_date)}}</small></td><td><strong class="client-name">{{row.customer_name||'Unnamed client'}}</strong><small>{{row.patient||'—'}}</small></td><td class="mobile-cell">{{row.mobile||'Not recorded'}}</td><td>{{row.branch||'—'}}</td><td><span class="source-badge" :title="'Source recorded on: '+row.source_from">{{row.source||'Not recorded'}}</span></td><td><span class="status-badge" :class="statusTone(row.status)"><i></i>{{row.status}}</span></td><td class="amount">{{money(row.grand_total,row.currency)}}</td><td class="amount" :class="{'balance-due':Number(row.outstanding_amount)>0}">{{money(row.outstanding_amount,row.currency)}}</td><td><button class="view-bill" :aria-label="'View bill '+row.name" @click="open(row.name)">View <span aria-hidden="true">↗</span></button></td></tr>
      <tr v-if="!rows.length"><td colspan="9"><div class="bill-empty" role="status"><span aria-hidden="true">▤</span><h3>{{busy?'Loading invoices…':error?'Invoices unavailable':'No bills found'}}</h3><p v-if="!busy&&!error">Try a different mobile number or widen the date range.</p><button v-if="!busy&&!error&&chips.length" @click="reset">Clear filters</button></div></td></tr>
    </tbody></table></div>
    <footer><span>{{rangeText}}</span><div><button :disabled="busy||!start" @click="load(Math.max(0,start-40),false)">← Previous</button><span>Page {{Math.floor(start/40)+1}}</span><button :disabled="busy||!more" @click="load(start+40,false)">Next →</button></div></footer>
  </section>
  <dialog ref="invoiceDialog" class="invoice-dialog" aria-labelledby="bill-detail-title" @close="closed">
    <header><div><span class="eyebrow">BILL DETAILS · VIEW ONLY</span><h2 id="bill-detail-title">{{invoice?.name||'Invoice details'}}</h2></div><button class="close-detail" aria-label="Close invoice details" @click="invoiceDialog.close()">×</button></header>
    <div class="detail-body"><p v-if="detailBusy" role="status">Loading invoice details…</p><p v-if="detailError" class="bill-error" role="alert">{{detailError}}</p>
      <template v-if="invoice"><div class="detail-client"><div><h3>{{invoice.customer_name}}</h3><p>{{invoice.patient||'Client'}} · {{invoice.mobile||'Mobile not recorded'}}</p></div><span class="status-badge" :class="statusTone(invoice.status)"><i></i>{{invoice.status}}</span></div>
      <dl class="detail-facts"><div><dt>Bill date</dt><dd>{{date(invoice.posting_date)}}</dd></div><div><dt>Due date</dt><dd>{{date(invoice.due_date)}}</dd></div><div><dt>Branch</dt><dd>{{invoice.branch||'—'}}</dd></div><div><dt>Client source</dt><dd>{{invoice.source||'Not recorded'}}<small v-if="invoice.source">From {{invoice.source_from.toLowerCase()}}</small></dd></div><div v-if="invoice.lead_source"><dt>Original lead source</dt><dd>{{invoice.lead_source}}</dd></div></dl>
      <div class="table-scroll"><table class="detail-items"><thead><tr><th>Service / Item</th><th>Quantity</th><th class="amount">Rate</th><th class="amount">Amount</th></tr></thead><tbody><tr v-for="item in invoice.items" :key="item.name"><td><strong>{{item.item_name}}</strong><small>{{item.item_code}}</small></td><td>{{item.qty}} {{item.uom}}</td><td class="amount">{{money(item.rate,invoice.currency)}}</td><td class="amount">{{money(item.amount,invoice.currency)}}</td></tr></tbody></table></div>
      <dl class="invoice-totals"><div><dt>Net total</dt><dd>{{money(invoice.net_total,invoice.currency)}}</dd></div><div v-if="Number(invoice.discount_amount)"><dt>Discount</dt><dd>{{money(invoice.discount_amount,invoice.currency)}}</dd></div><div><dt>Taxes</dt><dd>{{money(invoice.total_taxes_and_charges,invoice.currency)}}</dd></div><div class="grand-total"><dt>Bill total</dt><dd>{{money(invoice.grand_total,invoice.currency)}}</dd></div><div class="due-total"><dt>Outstanding balance</dt><dd>{{money(invoice.outstanding_amount,invoice.currency)}}</dd></div></dl></template>
    </div><footer><span>Invoice information is available for viewing.</span><button class="apply-button" @click="invoiceDialog.close()">Done</button></footer>
  </dialog>
</div>
</template>

<style scoped>
