umns:repeat(5,minmax(0,1fr));gap:12px}.filter-actions{display:flex;gap:10px;align-items:center;padding-top:17px;margin-top:18px;border-top:1px solid #edf1ec}.filter-help{font-size:10px;color:#849188;flex:1}.reset-button,.refresh-button{background:#fff;border:1px solid #dfe6df;border-radius:7px;padding:9px 12px;color:#607468;font-size:11px}.apply-button{background:var(--bill-green);color:white;border:1px solid var(--bill-green);padding:10px 16px;border-radius:7px;font-size:11px;font-weight:650}.apply-button:hover{background:#123c30}.apply-button span{margin-left:12px}.filter-chips{display:flex;gap:7px;flex-wrap:wrap;margin-top:14px}.filter-chips>span{border-radius:6px;background:#f1f5f0;padding:5px 8px;font-size:10px;color:#718273}.filter-chips b{color:#3d6249;font-weight:650}.options-error{font-size:12px;color:#987136}.options-error button{background:none;border:0;color:var(--bill-green);text-decoration:underline}.bill-error{background:#fff1ef;color:#9d4438;padding:14px 18px;border:1px solid #efd4ce;border-radius:10px;margin:12px 0;font-size:13px}.bill-error button{margin-left:10px;border:0;background:none;text-decoration:underline;color:inherit}.bill-results>header{display:flex;align-items:center;justify-content:space-between;padding:20px 24px;gap:12px}.bill-results>header>div{display:flex;flex-direction:column;gap:6px}.bill-results>header span{font-size:11px;color:#88968c}.refresh-button span{font-size:16px!important;margin-right:5px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px;white-space:nowrap}th{padding:13px 18px;background:#f5f8f4;color:#7d8a80;font-size:9px;letter-spacing:.65px;text-transform:uppercase;text-align:left;font-weight:750;border-top:1px solid #edf1ec;border-bottom:1px solid #e6ece4}td{padding:17px 18px;border-bottom:1px solid #edf1ec;vertical-align:middle;color:#5a6e60}td small{display:block;margin-top:5px;font-size:10px;color:#99a497}.client-name{font-size:12px;color:#36543e;font-weight:650}tbody tr:hover{